import re

def url_basename(url):
    # Normalize URL to handle scheme and optional www
    # Remove scheme if present
    if url.startswith('http://'):
        url = url[7:]
    elif url.startswith('https://'):
        url = url[8:]
    # Remove leading // if present (e.g., //example.com/path)
    if url.startswith('//'):
        url = url[2:]
    # Split by '/' to get path components
    parts = url.split('/')
    # Filter out empty parts and query/fragment
    path_parts = []
    for part in parts:
        if '?' in part or '#' in part:
            part = part.split('?')[0].split('#')[0]
        if part:
            path_parts.append(part)
    # The basename is the last non-empty path component
    if not path_parts:
        return ''
    return path_parts[-1]

