from urllib.parse import urlparse

def url_basename(url):
    parsed = urlparse(url)
    path = parsed.path
    if not path:
        return ''
    parts = path.split('/')
    basename = parts[-1]
    if basename == '':
        if len(parts) >= 2:
            basename = parts[-2]
        else:
            return ''
    return basename

